"""Freeze all tangent-seed and inverse-image outcomes without rewriting earlier packets."""
import hashlib,json,shutil
from pathlib import Path

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    repo=Path(__file__).resolve().parents[1];scratch=Path('D:/Codex/chaos-attractor-search-20261031');root=repo/'results/raar-folding';root.mkdir(exist_ok=False)
    mapping={'seeds':'raar-cycle-seeds01','hires':'raar-cycle-seeds-hires01','render-initial':'raar-cycle-seeds-render01','render-crop':'raar-cycle-seeds-render02','render-hires-initial':'raar-cycle-seeds-render03','render':'raar-cycle-seeds-render04','preimages-near':'raar-preimages01','preimages-global':'raar-preimages02','inverse-proposal':'raar-inverse-proposal01','inverse-proof-initial':'raar-inverse-proof01','inverse-proof':'raar-inverse-proof02','inverse-independent':'raar-inverse-independent01','inverse-render-initial':'raar-preimages-render01','inverse-render':'raar-preimages-render02'}
    copied=[]
    for dest,source in mapping.items():
        for p in sorted((scratch/source).rglob('*')):
            if not p.is_file() or '__pycache__' in p.parts:continue
            q=root/dest/p.relative_to(scratch/source);q.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,q);assert sha(p)==sha(q);copied.append(dict(source=str(p),path=q.relative_to(root).as_posix(),sha256=sha(q),bytes=q.stat().st_size))
    (root/'provenance.json').write_text(json.dumps(copied,indent=2),encoding='utf-8')
    prior=root/'priority';prior.mkdir();pdf=scratch/'raar-folding-priority/elser-2007.pdf'
    review=dict(date='2026-11-01',source=dict(title='Searching with iterated maps',authors=['V. Elser','I. Rankenburg','P. Thibault'],year=2007,doi='10.1073/pnas.0606359104',url='https://pi.math.cornell.edu/~web401/keith.protein.pdf',pdf_sha256=sha(pdf),pdf_bytes=pdf.stat().st_size,pages='Publisher cover followed by article pages 418–423',review_scope='Main article text read, including difference-map formula, strange-attractor interpretation, all application sections and conclusions; Figure 3 inspected as a schematic. Supplementary information not reviewed. Third-party full text is not redistributed.',finding='Projection/difference-map search chaos and circle-product Fourier constraints are established. The protein-folding circle is a schematic for a high-dimensional covalent-geometry constraint, not a study of two spatial circumferences. The article does not establish priority for the present exact RAAR pair. This is not an inequivalence proof.'),queries=['"Douglas-Rachford" "circles" "attractor"','"alternating reflections" "circles" "chaos"','"RAAR" "strange attractor"','"projection" "skew circles" dynamics','"RAAR" "preimages"','"Douglas Rachford" "noninvertible"'],outcome='No exact match located in this bounded review. Neither historical uniqueness nor a new attractor class is established.',other_reviews=['results/raar-circles/priority/review.json','results/raar-cycle-structure/priority/review.json'])
    (prior/'review.json').write_text(json.dumps(review,indent=2),encoding='utf-8')
    for folder,names in [('render',['raar-cycle-unfolding.gif','raar-cycle-unfolding.png','raar-cycle-seed-controls.png']),('inverse-render',['raar-four-preimages.png'])]:
        for name in names:shutil.copy2(root/folder/name,repo/'docs/assets'/name)
    (root/'README.md').write_text('# Spatial RAAR: tangent-seed evolution and complete preimages\n\nAll six declared seed experiments, both numerical inverse searches, both interval-Sturm certificate revisions, independent nested-reflector certificates and all visual revisions are retained. Earlier RAAR packets are unchanged. Source paths in reports are provenance; use the local folders mapped in provenance.json.\n\nThe final figures are in `render` and `inverse-render`. Earlier versions retain their original annotations; the corrected final rendering scope in `render/analysis.json` supersedes earlier image-resampling wording. Every point contributes to the histograms. The final GIF uses native histogram pixels after a common empty-margin crop.\n\nThe near-cloud search found one numerical preimage per target. The subsequent global search and interval certificates found exactly two or four regular-domain preimages. Additional inputs are off the finite reference cloud: noninjectivity of the full map does not establish noninjectivity on an attracting set.\n\nRun `python research/verify_raar_folding.py` from the repository root. See [the report](../../docs/raar-folding.md) and [the manuscript](../../docs/raar-folding/manuscript.md).\n',encoding='utf-8')
    files=[dict(path=p.relative_to(root).as_posix(),bytes=p.stat().st_size,sha256=sha(p)) for p in sorted(root.rglob('*')) if p.is_file()]
    (root/'manifest.json').write_text(json.dumps(dict(files=files),indent=2),encoding='utf-8');print(json.dumps(dict(files=len(files),bytes=sum(r['bytes'] for r in files),manifest_sha256=sha(root/'manifest.json'))))
if __name__=='__main__':main()
